arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotalHandler.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalCommand(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalCommand command) => default;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/CalculatePayableTotalTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class CalculatePayableTotalTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(new CalculatePayableTotalCommand("Gold", 100.00m));

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Assert|Expected|Actual|Failed|Passed" | head -20

